<?php $title = 'Koszyk | ShopStack'; require __DIR__ . '/../layouts/header.php'; ?><p class="eyebrow">TWOJE ZAMÓWIENIE</p><h1>Koszyk</h1><?php if (!$items): ?><div class="empty"><p>Twój koszyk jest pusty.</p><a class="button" href="<?= e($config['url']) ?>/products">Przejdź do produktów</a></div><?php else: ?><form method="post" action="<?= e($config['url']) ?>/cart/update"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><div class="table-list"><?php foreach ($items as $item): ?><div class="line-item"><div><strong><?= e($item['name']) ?></strong><small><?= money($item['price']) ?> / szt.</small></div><input type="number" name="quantities[<?= e($item['id']) ?>]" value="<?= e($item['quantity']) ?>" min="0" max="<?= e($item['stock']) ?>"><strong><?= money($item['subtotal']) ?></strong><form></form><button class="link-button" formaction="<?= e($config['url']) ?>/cart/remove/<?= e($item['id']) ?>">Usuń</button></div><?php endforeach; ?></div><div class="cart-total"><span>Razem</span><strong><?= money($total) ?></strong></div><button class="button">Aktualizuj koszyk</button> <a class="button secondary" href="<?= e($config['url']) ?>/checkout">Przejdź do kasy</a></form><?php endif; ?><?php require __DIR__ . '/../layouts/footer.php'; ?>
